from pathlib import Path
# 2026-09-08 10:11 — trigger current-day patch verification after governance lock
TARGET=Path('2026 09 08 9:59 NAYANET HUB')
MARKER='NAYANET-HUB-RIGHT-SIDEBAR-FEED-MIRROR-V1'
CSS='''<style id="nayanet-right-sidebar-feed-mirror-style">.activationRail{display:none!important}.homeWorkspace{display:block!important;grid-template-columns:1fr!important}.homeFeed{width:100%!important;max-width:none!important}#nayanet-elite-feed{width:100%!important;max-width:none!important}.nhm-actions{display:flex;gap:8px;flex-wrap:wrap;margin:0 18px 18px;padding-top:14px;border-top:1px solid #ffffff14}.nhm-actions button{min-height:40px;padding:0 13px;border:1px solid #8b63ff66;border-radius:11px;background:linear-gradient(145deg,#17111f,#08080c);color:#fff;font-size:8px;font-weight:1000;letter-spacing:.05em;box-shadow:inset 0 1px #fff4,0 8px 18px #0009}.nhm-actions button:hover,.nhm-actions button.active{border-color:#d86cff;box-shadow:0 0 22px #d86cff22}.nhm-actions .rank{color:#ffd98a}.nhm-actions .comment{border-color:#55b9ee66}@media(max-width:900px){.activationRail{display:none!important}.homeWorkspace{display:block!important}.nhm-actions button{flex:1 1 auto}}</style>'''
JS='''<script id="nayanet-right-sidebar-feed-mirror-runtime">(()=>{'use strict';const ROOT='#nayanet-elite-feed';const clean=s=>String(s||'').replace(/\\s+/g,' ').trim();const state=()=>{try{return JSON.parse(localStorage.getItem('nayanet:feed-mirror-actions')||'{}')}catch{return{}}};const save=s=>{try{localStorage.setItem('nayanet:feed-mirror-actions',JSON.stringify(s))}catch{}};function getBlocks(){return [...document.querySelectorAll(ROOT+' .n3-block')].filter(b=>!b.classList.contains('nhm-generated'))}function actions(block){if(block.querySelector('.nhm-actions'))return;const title=clean(block.querySelector('.n3-title')?.textContent||'Intelligent Block'),key=title.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,90),st=state(),a=st[key]||{},bar=document.createElement('div');bar.className='nhm-actions';bar.innerHTML='<button data-a="share">＋ SHARE</button><button data-a="like">👍 LIKE</button><button data-a="love">♥ LOVE</button><button class="rank" data-a="rank">★ RANK</button><button class="comment" data-a="comment">💬 COMMENT</button><button data-a="save">🔖 SAVE</button>';bar.querySelectorAll('button').forEach(btn=>{const k=btn.dataset.a;if(a[k])btn.classList.add('active');btn.onclick=()=>{const s=state();s[key]=s[key]||{};if(k==='share'){const text=title+'\\n\\n'+clean(block.querySelector('.n3-nutshell p')?.textContent||'')+'\\n\\nNayaNET — Create. Connect. Grow with US.';if(navigator.share)navigator.share({title,text,url:location.href}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>{btn.textContent='✓ COPIED';setTimeout(()=>btn.textContent='＋ SHARE',1200)});return}if(k==='comment'){const text=prompt('Add a comment to this Intelligent Block:');if(!text||!text.trim())return;s[key].comments=s[key].comments||[];s[key].comments.push({text:text.trim(),createdAt:new Date().toISOString()});btn.textContent='💬 COMMENT '+s[key].comments.length}else if(k==='rank'){const n=Number(prompt('How valuable is this intelligence? Enter 1–5.',s[key].rank||''));if(!Number.isFinite(n)||n<1||n>5)return;s[key].rank=Math.round(n);btn.textContent='★ RANK '+s[key].rank+'/5'}else{s[key][k]=!s[key][k];btn.classList.toggle('active',!!s[key][k])}save(s)}});const footer=block.querySelector('.n3-footer');if(footer)footer.insertAdjacentElement('beforebegin',bar);else block.appendChild(bar)}function addActions(){getBlocks().forEach(actions)}function render(view){const feed=document.querySelector(ROOT),body=feed?.querySelector('.n3-body');if(!feed||!body)return;const originals=[...body.children].filter(b=>b.classList.contains('n3-block')&&!b.classList.contains('nhm-generated'));if(!originals.length)return;body.innerHTML=originals.map((b,i)=>{const c=b.cloneNode(true);c.classList.add('nhm-generated');const e=c.querySelector('.n3-eyebrow');if(e)e.innerHTML='<span class="n3-led"></span><b>INTELLIGENT BLOCK</b> · '+view.toUpperCase()+(view==='activity'?' · EVENT '+String(i+1).padStart(2,'0'):'');return c.outerHTML}).join('');addActions()}function mirror(){const feed=document.querySelector(ROOT);if(!feed||feed.dataset.nhmBound)return;feed.dataset.nhmBound='1';feed.addEventListener('click',e=>{const tab=e.target.closest('.n3-tab');if(!tab)return;e.preventDefault();e.stopImmediatePropagation();feed.querySelectorAll('.n3-tab').forEach(x=>{x.classList.toggle('active',x===tab);x.setAttribute('aria-selected',String(x===tab))});render(tab.dataset.view||'collective')},true)}function guard(){const left=document.querySelector('.sidebar');if(!left)return;const rail=document.querySelector('.activationRail');if(rail)rail.style.setProperty('display','none','important');const ws=document.querySelector('.homeWorkspace');if(ws)ws.style.setProperty('grid-template-columns','1fr','important');addActions()}function boot(){mirror();guard();let n=0;const t=setInterval(()=>{guard();if(++n>18)clearInterval(t)},350)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();</script>'''

def apply():
    html=TARGET.read_text(encoding='utf-8')
    if MARKER in html:return False
    payload=CSS+'\n'+JS+'\n<!-- '+MARKER+' -->\n'
    html=html.replace('</head>',payload+'</head>',1)
    TARGET.write_text(html,encoding='utf-8')
    return True
if __name__=='__main__':print('PATCHED' if apply() else 'ALREADY_PATCHED')
